package io.github.ningpp.compat;

import java.util.concurrent.CompletableFuture;

/**
 * Mirrors the BCL {@code System.IAsyncDisposable} interface for converted
 * C# code (generated by CSharpToJava converter).
 *
 * <p>Blocking model (C18 design §1.2 / C38 design §5): converted {@code await}
 * becomes {@link CompletableFuture#join()} — a statement-level
 * {@code await x.DisposeAsync();} lowers to {@code x.disposeAsync().join();}.
 * A faulted dispose future therefore surfaces its failure from
 * {@code join()} as a {@link java.util.concurrent.CompletionException}
 * wrapping the real exception. Under the plain try/finally lowering that the
 * C# async-normalize pass emits by default (the measured net10 truth, fixture
 * T4), a dispose fault in {@code finally} masks the in-flight try fault.</p>
 */
public interface AsyncDisposable {

    /**
     * Mirrors {@code System.IAsyncDisposable.DisposeAsync()} (BCL return type
     * {@code System.Threading.Tasks.ValueTask}, mapped to
     * {@code CompletableFuture<Void>}).
     *
     * @return a future completed when the asynchronous release has finished
     */
    CompletableFuture<Void> disposeAsync();
}
